            unit_amount_decimal: string;
            /** Format: int64 */
            amount_cents: number;
            /**
             * Format: double
             * @description Tax rate as a percent (18.50 = 18.50%), up to 4-decimal precision. ADR-042/043.
             */
            tax_rate: number;
            /** Format: int64 */
            tax_amount_cents: number;
            tax_jurisdiction?: string;
            tax_code?: string;
